mapper.select:
SELECT T1.SETTLE_SEQ_NO SETTLE_SEQ_NO, T1.SETTLE_STATUS SETTLE_STATUS, T1.ORDER_ID ORDER_ID, T1.TRADE_ID TRADE_ID, T1.TRADE_DATE TRADE_DATE, T1.SETTLE_DATE SETTLE_DATE, T1.PORTFOLIO_ID PORTFOLIO_ID, concat(concat(sci.BUSI_ACCT_NO,':'),sci.ACCT_NAME) ACCT_NO, concat(concat(ssai.SEC_ACCT_ID,':'),ssai.SEC_ACCT_NAME) SEC_ACCT_ID, T1.TRADE_MARKET TRADE_MARKET, T1.TRADE_PLAT TRADE_PLAT, T1.FINPROD_ID FINPROD_ID, T1.SETTLE_NUM SETTLE_NUM, T1.SETTLE_AMT SETTLE_AMT, T1.BUSI_TYPE BUSI_TYPE, T1.COUNTER_ID COUNTER_ID, T1.ENTRUST_NO ENTRUST_NO, T2.FINPROD_NAME , T2.FINPROD_MARKET_ID , T3.PORTFOLIO_NAME, T4.COUNTER_NAME FROM TRD_MANUAL_SETTLE_INFO T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T3 ON T1.PORTFOLIO_ID = T3.PORTFOLIO_ID Left join MST_COUNTER_PARTY T4 ON T4.COUNTER_ID = T1.COUNTER_ID
LEFT JOIN STL_CAPACCT_INFO sci ON T1.ACCT_NO = sci.ACCT_NO LEFT JOIN STL_SEC_ACCT_INFO ssai ON T1.SEC_ACCT_ID = ssai.SEC_ACCT_ID
AND T1.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userName})
AND ( T1.PORTFOLIO_ID IN
#{item}
OR T1.PORTFOLIO_ID IN
#{item}
)
and T1.TRADE_MARKET =#{tradeMarket}
and T1.FINPROD_ID like CONCAT('%',CONCAT(#{finprodMarketId}, '%'))
and T1.SETTLE_STATUS =#{settleStatus}
and T1.BUSI_TYPE =#{busiType}
and T1.TRADE_DATE >= to_date(#{tradeDateStart}, 'yyyy-MM-dd')
and T1.TRADE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
and T1.SETTLE_DATE >= to_date(#{settleDateStart}, 'yyyy-MM-dd')
and T1.SETTLE_DATE <= to_date(#{settleDateEnd}, 'yyyy-MM-dd')

mapper.update:
UPDATE TRD_MANUAL_SETTLE_INFO SET

  SETTLE_DATE = SETTLE_DATE+1,

SETTLE_STATUS = #{settleStatus}


        and SETTLE_SEQ_NO =#{settleSeqNo}
